package com.bankpli.javabank.web;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc class ApplicationIntegrationTest{@Autowired MockMvc mvc;@Test void menuAndHealthContracts()throws Exception{mvc.perform(get("/api/health")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("UP"));mvc.perform(get("/api/menu")).andExpect(status().isOk()).andExpect(jsonPath("$[0].name").value("Customers"));}@Test void customerCrudContract()throws Exception{String json="{\"title\":\"Ms\",\"firstName\":\"Ada\",\"lastName\":\"Lovelace\",\"email\":\"ada@bank.test\",\"phone\":\"5551234567\",\"dateOfBirth\":\"1990-01-01\",\"creditScore\":750}";mvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(json)).andExpect(status().isCreated()).andExpect(jsonPath("$.firstName").value("Ada"));mvc.perform(get("/api/customers?q=Ada")).andExpect(status().isOk()).andExpect(jsonPath("$.content[0].lastName").value("Lovelace"));}}
